python3 -I - $R <<'EOF'
import json,hashlib,sys,os,re,subprocess
R=sys.argv[1]
def dg(g): return "sha256:"+hashlib.sha256(json.dumps(g,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()
g=json.load(open(R+'/.dev-graph/state/graph.json'))
p=json.load(open(R+'/.dev-graph/cache/decompose-input/c02-preview.json'))
rc=json.load(open(R+'/.dev-graph/state/package-registration-receipt-LT-FEATURE-001.json'))
print('cur',dg(g),g['graph_revision'],[k for k in g if k!='nodes'])
ids=[n['graph_node_id'] for n in g['nodes']];print(len(ids),len(set(ids)))
print('prev digest_after',p['graph_digest_after'],'rev',p['graph_revision_before'])
# planned
arts={a['graph_node_id']:a for a in p['artifacts']}
pl=[]
for n in p['planned_nodes']:
    m=dict(n);m['file_path']=arts[n['graph_node_id']]['file_path'];pl.append(m)
g2=json.loads(json.dumps(g));g2['nodes']+=pl;g2['graph_revision']=p['graph_revision_after']
print('planned',dg(g2),'matches receipt?',dg(g2)==p['graph_digest_after'])
g3=json.loads(json.dumps(g));g3['nodes']+=p['planned_nodes'];g3['graph_revision']=4
print('planned raw',dg(g3))
open('/dev/stdout','w').write('')
json.dump(g2,open('/dev/stderr','w')) if False else None
# structural
for gg,l in((g,'cur'),(g2,'plan')):
    N={n['graph_node_id']:n for n in gg['nodes']}
    for n in gg['nodes']:
        for d in n.get('depends_on',[]):
            if d not in N: print(l,'dangling',n['graph_node_id'],d)
        fp=n.get('file_path')
        if fp and (os.path.isabs(fp) or '..' in fp.split('/')): print(l,'path',fp)
    # cycle
    st={}
    def v(x,path):
        if st.get(x)==1: print(l,'CYCLE',path);return
        if st.get(x)==2:return
        st[x]=1
        for d in N[x].get('depends_on',[]):
            if d in N: v(d,path+[d])
        st[x]=2
    for x in N:v(x,[x])
    macro=[n for n in gg['nodes'] if n['artifact_kind'] in('feature','architecture')]
    print(l,'macro',[(n['graph_node_id'],n.get('parent_feature'),n.get('phase_ref'),n.get('feature_package_id')) for n in macro])
    tasks=[n for n in gg['nodes'] if n['artifact_kind']=='task']
    print(l,'tasks',len(tasks))
    refd={n.get('parent_feature') for n in tasks}; print(refd)
    for n in tasks:
        e=n['graph_node_id']
        if n.get('parent_feature')!='LT-FEATURE-001' or n.get('feature_package_id')!='feature-package/LT-FEATURE-001' or not e.startswith('LT-FEATURE-001-P'+(n.get('phase_ref') or '')[1:]) : print('task mismatch',e,n.get('parent_feature'),n.get('phase_ref'),n.get('feature_package_id'))
        if not os.path.exists(R+'/'+n['file_path']): print('missing file',n['file_path'])
    print(sorted(n.get('phase_ref') for n in tasks)==[f'P{i:02d}' for i in range(1,14)], rc['node_ids']==sorted(n['graph_node_id'] for n in tasks))
    for n in gg['nodes']:
        if n['artifact_kind']!='task' and not os.path.exists(R+'/'+n['file_path']): print(l,'file absent on disk',n['graph_node_id'],n['file_path'])
json.dump(g2,sys.stdout) if False else None
open(os.environ.get('X','/dev/null'),'w')
print(json.dumps(g2))
EOF

